(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const map = window.__big.map;
  const chars = {};
  for (const k in map) { const s = String(map[k] || ''); for (const ch of s) { if (/[\u4e00-\u9fa5]/.test(ch)) chars[ch] = (chars[ch] || 0) + 1; } }
  const ranked = Object.keys(chars).sort((a, b) => chars[b] - chars[a]);
  // 原扫描用了前 400 个中文字做种子，这里取第 401~860 名（即当时没被用作种子的字）
  const fresh = ranked.slice(400, 860);
  const sample = fresh.filter((_, i) => i % 8 === 0).slice(0, 60);
  const before = Object.keys(map).length;
  const newVids = {};
  let reqs = 0, errs = 0;
  for (const ch of sample) {
    try {
      const r = await fetch('/draco-ms/mms/template/property/value/search', { method: 'POST', headers: { 'Content-Type': 'application/json' }, credentials: 'include', body: JSON.stringify({ cat_id: 5908, pid: 5, template_pid: 642609, page_num: 1, page_size: 1000, value: ch }) });
      const j = await r.json();
      reqs++;
      if (j && j.success && Array.isArray(j.result)) { for (const x of j.result) if (!(x.vid in map)) newVids[x.vid] = x.value; }
    } catch (e) { errs++; }
    await sleep(120);
  }
  const after = Object.keys(map).length;
  for (const k in newVids) map[k] = newVids[k];
  return JSON.stringify({ charsAvailable: ranked.length, freshCharsTotal: fresh.length, sampled: sample.length, reqs: reqs, errs: errs, before: before, after: Object.keys(map).length, newFound: Object.keys(newVids).length, sampleChars: sample.slice(0, 12), newSample: Object.entries(newVids).slice(0, 6) });
